static void ide_dump_ata_error ( ide_drive_t * drive , u8 err ) { printk ( KERN_CONT "{ " ) ; if ( err & ATA_ABORTED ) { printk ( KERN_CONT "DriveStatusError " ) ; } if ( err & ATA_ICRC ) { printk ( KERN_CONT "%s" , ( err & ATA_ABORTED ) ?"BadCRC " : "BadSector " ) ; } if ( err & ATA_UNC ) { printk ( KERN_CONT "UncorrectableError " ) ; } if ( err & ATA_IDNF ) { printk ( KERN_CONT "SectorIdNotFound " ) ; } if ( err & ATA_TRK0NF ) { printk ( KERN_CONT "TrackZeroNotFound " ) ; } printk ( KERN_CONT "}" ) ; if ( ( err & ( ATA_BBK | ATA_ABORTED ) ) == ATA_BBK || ( err & ( ATA_UNC | ATA_IDNF | ATA_AMNF ) ) ) { struct request * rq = drive -> hwif -> rq ; ide_dump_sector ( drive ) ; if ( rq ) { printk ( KERN_CONT ", sector=%llu" , ( unsigned long long ) blk_rq_pos ( rq ) ) ; } } printk ( KERN_CONT "\n" ) ; } 